const r = await tools.exec_command({cmd:"cat > "$STAMPED_JUDGE_OUTPUT/commands/verify_copy.py" <<'PY'
import hashlib, json, os, pathlib, stat
root = pathlib.Path(os.environ['STAMPED_JUDGE_TARGET'])
manifest = json.load(open(os.environ['STAMPED_OPERATIONAL_MANIFEST']))
prefix='content/workspace'
expected={}
for e in manifest['entries']:
    p=e['path']
    if p==prefix: rel='.'
    elif p.startswith(prefix+'/'): rel=p[len(prefix)+1:]
    else: continue
    expected[rel]=e
observed=[]
metadata=[]
for rel,e in expected.items():
    p=root if rel=='.' else root/rel
    try: st=p.lstat()
    except FileNotFoundError:
        observed.append({'path':rel,'difference':'missing'}); continue
    kind='symlink' if stat.S_ISLNK(st.st_mode) else 'directory' if stat.S_ISDIR(st.st_mode) else 'file' if stat.S_ISREG(st.st_mode) else 'other'
    if kind != e['kind']:
        observed.append({'path':rel,'difference':'kind','expected':e['kind'],'actual':kind}); continue
    if kind=='symlink': actual=hashlib.sha256(os.readlink(p).encode()).hexdigest()
    elif kind=='file':
        h=hashlib.sha256()
        with p.open('rb') as f:
            for block in iter(lambda:f.read(1<<20),b''): h.update(block)
        actual=h.hexdigest()
    else: actual=None
    changed=(actual is not None and actual!=e.get('sha256'))
    mode_changed=kind!='symlink' and stat.S_IMODE(st.st_mode)!=e.get('mode')
    if changed or mode_changed:
        record={'path':rel,'difference':'sha256' if changed else 'mode','expected_sha256':e.get('sha256'),'actual_sha256':actual,'expected_mode':e.get('mode'),'actual_mode':stat.S_IMODE(st.st_mode)}
        if kind=='file' and rel.startswith('.git/annex/keysdb/') and pathlib.PurePosixPath(rel).name in {'db','db-shm','db-wal'}:
            metadata.append(record)
        else: observed.append(record)
# Check for paths not represented by the complete operational manifest.
for dp, dns, fns in os.walk(root, topdown=True, followlinks=False):
    base=pathlib.Path(dp)
    for name in list(dns)+fns:
        p=base/name
        rel=p.relative_to(root).as_posix()
        if rel not in expected: observed.append({'path':rel,'difference':'unexpected'})
        if p.is_symlink() and name in dns: dns.remove(name)
print(json.dumps({'operational_manifest_matches':not observed,'non_metadata_differences':observed,'annex_keydb_metadata_differences':metadata,'entry_count':len(expected)},indent=2))
PY
